package com.moneylab.superledger.mobile;

import org.json.JSONArray;
import org.json.JSONObject;
import android.content.Context;
import java.nio.file.Files;
import java.lang.reflect.Field;

/** Fixed JS/Java schedule fixtures and v4 storage regressions; no Android runtime or network. */
public final class Schema4Test {
    private static int checks;
    private interface Work {void run()throws Exception;}
    private static void check(boolean pass,String label){checks++;if(!pass)throw new AssertionError(label);}
    private static void rejects(Work work,String label)throws Exception{try{work.run();throw new AssertionError(label);}catch(AssertionError failure){throw failure;}catch(Exception expected){checks++;}}
    private static JSONObject state(int interval)throws Exception {
        JSONObject state=MobileLedger.emptyState().put("schemaVersion",4);
        state.getJSONArray("accounts").put(MobileLedgerTest.account("bank","CNY",100000,null));
        JSONObject sub=MobileLedgerTest.subscription("fixture","bank",101,"2024-01-31",true).put("startHour",9).put("billingHour",18);
        if(interval!=1)sub.put("intervalMonths",interval);state.getJSONArray("subscriptions").put(sub);return state;
    }
    private static JSONObject plan(JSONObject state)throws Exception{return state.getJSONArray("subscriptions").getJSONObject(0);}
    private static JSONObject goal()throws Exception{return new JSONObject().put("id","goal").put("name","旅行").put("target",10001).put("saved",0).put("color","#abcdef").put("deadline","2026-03-31");}
    public static void main(String[] args)throws Exception {
        String[][] expected={{"2024-01-31","2024-04-30","2024-07-31","2024-10-31","2025-01-31"},{"2024-01-31","2024-07-31","2025-01-31"},{"2024-01-31","2025-01-31"}};
        int[] intervals={3,6,12};String[] next={"2025-04-30","2025-07-31","2026-01-31"};
        for(int n=0;n<intervals.length;n++){
            JSONObject applied=MobileLedger.applyRecurring(state(intervals[n]),"2025-02-28",18),book=applied.getJSONObject("state");JSONArray added=applied.getJSONArray("added");check(added.length()==expected[n].length,"fixed fixture charge count");
            for(int i=0;i<added.length();i++){JSONObject tx=added.getJSONObject(i);check(tx.getString("date").equals(expected[n][i]),"fixed JS/Java due date");check(tx.getString("occurrenceKey").equals("fixture:"+expected[n][i].substring(0,7)),"period key unchanged");check(tx.getString("id").equals("rec_fixture_"+expected[n][i].substring(0,7).replace("-","")),"deterministic ID unchanged");}
            check(MobileLedger.nextSubscriptionDue(plan(book),"2025-02-28").equals(next[n]),"fixed JS/Java next due");check(MobileLedger.applyRecurring(book,"2025-02-28",18).getJSONArray("added").length()==0,"no repeat charges");
        }
        JSONObject monthlyFixture=MobileLedger.applyRecurring(state(1),"2025-02-28",18);String[] monthlyDates={"2024-01-31","2024-02-29","2024-03-31","2024-04-30","2024-05-31","2024-06-30","2024-07-31","2024-08-31","2024-09-30","2024-10-31","2024-11-30","2024-12-31","2025-01-31","2025-02-28"};for(int i=0;i<monthlyDates.length;i++)check(monthlyFixture.getJSONArray("added").getJSONObject(i).getString("date").equals(monthlyDates[i]),"fixed monthly JS/Java fixture");check(MobileLedger.nextSubscriptionDue(plan(monthlyFixture.getJSONObject("state")),"2025-02-28").equals("2025-03-31"),"fixed monthly next due");
        JSONObject exactFx=state(3);exactFx.getJSONArray("accounts").getJSONObject(0).put("currency","USD").put("cnyRate","1.5");plan(exactFx).put("currency","USD").put("amount",1);check(MobileLedger.recurringTotal(exactFx,false)==1&&MobileLedger.recurringTotal(exactFx,true)==8,"shared USD one cent fixture converts CNY before average");
        JSONObject leap=state(12);plan(leap).put("startDate","2024-02-29");JSONObject leapApplied=MobileLedger.applyRecurring(leap,"2025-02-28",18);check(leapApplied.getJSONArray("added").getJSONObject(1).getString("date").equals("2025-02-28"),"annual leap clamp");check(MobileLedger.nextSubscriptionDue(plan(leapApplied.getJSONObject("state")),"2025-02-28").equals("2026-02-28"),"annual next February");
        JSONObject unfunded=state(3);unfunded.getJSONArray("accounts").getJSONObject(0).put("openingBalance",100);JSONObject unpaid=MobileLedger.applyRecurring(unfunded,"2024-07-31",18);check(unpaid.getJSONArray("added").length()==0&&plan(unpaid.getJSONObject("state")).getJSONArray("processedOccurrences").length()==0,"unfunded periods stay pending");
        JSONObject paused=plan(state(6)).put("active",false);JSONObject resumed=MobileLedger.setSubscriptionActive(paused,true,"2025-01-31",18);check(resumed.getJSONArray("processedOccurrences").length()==2,"pause skips six-month grid only");check(MobileLedger.nextSubscriptionDue(resumed,"2025-01-31").equals("2025-01-31"),"same-hour resume remains due");
        JSONObject renew=state(3);plan(renew).put("expiresOn","2024-01-31");JSONObject renewed=MobileLedger.applyRecurring(renew,"2024-04-30",18).getJSONObject("state");check(plan(renewed).getString("expiresOn").equals("2024-07-31"),"two quarterly charges advance six months");MobileLedger.validateState(renewed);
        JSONObject changed=MobileLedger.changeSubscriptionInterval(plan(state(12)).put("processedOccurrences",new JSONArray().put("fixture:2024-01")),1,"2024-08-15");check(!changed.has("intervalMonths")&&changed.getJSONArray("processedOccurrences").length()==7,"annual to monthly skips old grid before today");check(MobileLedger.nextSubscriptionDue(changed,"2024-08-15").equals("2024-08-31"),"annual to monthly next due");JSONObject annual=MobileLedger.changeSubscriptionInterval(changed,12,"2024-08-15");check(annual.getJSONArray("processedOccurrences").length()==7&&MobileLedger.nextSubscriptionDue(annual,"2024-08-15").equals("2025-01-31"),"monthly to annual retains off-grid keys");
        JSONObject fee=state(12);check(MobileLedger.recurringTotal(fee,false)==8&&MobileLedger.recurringTotal(fee,true)==101,"annual estimate is not rounded monthly times twelve");fee.getJSONArray("accounts").getJSONObject(0).put("currency","JPY").put("cnyRate","0.005");plan(fee).put("currency","JPY").put("amount",1).put("intervalMonths",3);check(MobileLedger.recurringTotal(fee,false)==0&&MobileLedger.recurringTotal(fee,true)==4,"convert to CNY before averaging");
        JSONObject max=state(12);plan(max).put("amount",MobileLedger.MAX_MONEY);MobileLedger.validateState(max);plan(max).put("intervalMonths",6);rejects(()->MobileLedger.validateState(max),"true annual cap");
        for(Object invalid:new Object[]{0,2,4,13,1.5,"3",JSONObject.NULL}){JSONObject bad=state(3);plan(bad).put("intervalMonths",invalid);rejects(()->MobileLedger.validateState(bad),"invalid interval rejected");}
        JSONObject once=state(3);plan(once).put("recurring",false);rejects(()->MobileLedger.validateState(once),"one-time interval rejected");
        for(String field:new String[]{"categoryBudgets","customCategories","deadline","intervalMonths"}){JSONObject gated=state(1).put("schemaVersion",3);if(field.equals("deadline"))gated.getJSONArray("goals").put(goal());else if(field.equals("intervalMonths"))plan(gated).put(field,1);else gated.getJSONObject("settings").put(field,field.equals("categoryBudgets")?new JSONObject():new JSONObject().put("expense",new JSONArray()).put("income",new JSONArray()));rejects(()->MobileLedger.validateState(gated),"all v4 fields gated");}
        JSONObject custom=state(1);custom.getJSONObject("settings").put("customCategories",new JSONObject().put("expense",new JSONArray().put("宠物")).put("income",new JSONArray())).put("categoryBudgets",new JSONObject().put("宠物",1234));custom.getJSONArray("goals").put(goal());MobileLedger.validateState(custom);check(java.util.Arrays.asList(MobileLedger.categories(custom.getJSONObject("settings"),"expense")).contains("宠物"),"picker includes custom category");
        for(Object invalid:new Object[]{0,-1,1.5,"1",JSONObject.NULL}){JSONObject bad=MobileLedger.copy(custom);bad.getJSONObject("settings").getJSONObject("categoryBudgets").put("宠物",invalid);rejects(()->MobileLedger.validateState(bad),"invalid budget rejected");}
        for(Object invalid:new Object[]{"","\u00a0",12,JSONObject.NULL,"其他收入","餐饮美食"}){JSONObject bad=MobileLedger.copy(custom);bad.getJSONObject("settings").getJSONObject("customCategories").getJSONArray("expense").put(invalid);rejects(()->MobileLedger.validateState(bad),"invalid custom category rejected");}
        JSONObject duplicate=MobileLedger.copy(custom);duplicate.getJSONObject("settings").getJSONObject("customCategories").getJSONArray("expense").put("宠物");rejects(()->MobileLedger.validateState(duplicate),"duplicate category rejected");
        for(String invalid:new String[]{"2025-02-29","2026-1-01","","2200-01-01"}){JSONObject bad=MobileLedger.copy(custom);bad.getJSONArray("goals").getJSONObject(0).put("deadline",invalid);rejects(()->MobileLedger.validateState(bad),"invalid deadline rejected");}
        check(MobileLedger.goalDeadline(goal(),"2026-01-31").getLong("monthlySaving")==5001,"calendar months and ceil cents");check(MobileLedger.goalDeadline(goal(),"2026-03-30").getLong("monthlySaving")==10001,"less than one month");check(MobileLedger.goalDeadline(goal(),"2026-04-01").getBoolean("overdue"),"expired unfinished wish");check(!MobileLedger.goalDeadline(goal().put("saved",10001),"2026-01-31").has("monthlySaving"),"finished wish has no suggestion");
        Field singleton=LedgerStore.class.getDeclaredField("instance");singleton.setAccessible(true);singleton.set(null,null);java.io.File directory=Files.createTempDirectory("schema4-store-").toFile();LedgerStore store=LedgerStore.get(new Context(directory));store.saveAccount(MobileLedgerTest.account("bank","CNY",100000,null));store.saveSettings(new JSONObject().put("unknownExtension",new JSONObject().put("keep","opaque")).put("customCategories",custom.getJSONObject("settings").getJSONObject("customCategories")).put("categoryBudgets",custom.getJSONObject("settings").getJSONObject("categoryBudgets")));store.saveGoal(goal());store.saveSettings(new JSONObject().put("monthlyBudget",5678));JSONObject saved=store.snapshot().getJSONObject("state");check(saved.getInt("schemaVersion")==4&&saved.getJSONObject("settings").getJSONObject("unknownExtension").getString("keep").equals("opaque"),"settings edit preserves extensions and promotes v4");singleton.set(null,null);store=LedgerStore.get(new Context(directory));check(store.snapshot().getJSONObject("state").getJSONArray("goals").getJSONObject(0).has("deadline"),"deadline durable roundtrip");store.saveGoal(new JSONObject().put("id","goal").put("deadline",""));store.saveSettings(new JSONObject().put("customCategories",new JSONObject().put("expense",new JSONArray()).put("income",new JSONArray())).put("categoryBudgets",new JSONObject()));saved=store.snapshot().getJSONObject("state");check(!saved.getJSONObject("settings").has("categoryBudgets")&&!saved.getJSONObject("settings").has("customCategories")&&!saved.getJSONArray("goals").getJSONObject(0).has("deadline"),"empty optional fields omitted");check(saved.getInt("schemaVersion")==4,"schema never silently downgrades");
        String today=LedgerStore.today(),start=java.time.LocalDate.parse(today).minusMonths(7).withDayOfMonth(1).toString();store.saveSubscription(MobileLedgerTest.subscription("edited_cycle","bank",101,start,true).put("intervalMonths",12).put("expiresOn",start));JSONObject annualStored=MobileLedger.find(store.snapshot().getJSONObject("state").getJSONArray("subscriptions"),"edited_cycle");String expiry=annualStored.getString("expiresOn");int previousTransactions=store.snapshot().getJSONObject("state").getJSONArray("transactions").length();store.saveSubscription(new JSONObject().put("id","edited_cycle").put("intervalMonths",1));JSONObject monthlyStored=MobileLedger.find(store.snapshot().getJSONObject("state").getJSONArray("subscriptions"),"edited_cycle");check(!monthlyStored.has("intervalMonths"),"saved monthly interval omitted");JSONArray storedTransactions=store.snapshot().getJSONObject("state").getJSONArray("transactions");for(int i=previousTransactions;i<storedTransactions.length();i++)check(storedTransactions.getJSONObject(i).getString("date").compareTo(today)>=0,"actual store interval edit never backfills past months");check(MobileLedger.nextSubscriptionDue(monthlyStored,today).compareTo(today)>=0,"actual store next due is current/future grid");check(monthlyStored.getJSONObject("expiryRenewal").getString("baseDate").equals(expiry),"cycle edit resets anchor without rescaling paid history");store.saveSubscription(new JSONObject().put("id","edited_cycle").put("intervalMonths",12));check(MobileLedger.nextSubscriptionDue(MobileLedger.find(store.snapshot().getJSONObject("state").getJSONArray("subscriptions"),"edited_cycle"),today).equals(MobileLedger.addMonthsDue(start,12,31)),"actual store monthly-to-annual returns original annual grid");
        SyncClient.Pairing pairing=new SyncClient.Pairing();pairing.expiresAt=System.currentTimeMillis()+60000;pairing.supportedSchemaVersion=3;try{SyncClient.synchronize(pairing,new JSONObject().put("schemaVersion",4));throw new AssertionError("old desktop accepted");}catch(Exception expectedError){check(expectedError.getMessage().contains("电脑")&&expectedError.getMessage().contains("4"),"old desktop gets explicit version update guidance before encryption/network");}
        System.out.println("Schema4: "+checks+" cycle, validation, storage and parity checks passed");
    }
}
